import urllib.request, urllib.parse, json, time

def s2(query, limit=15):
    url = "https://api.semanticscholar.org/graph/v1/paper/search?" + urllib.parse.urlencode({
        "query": query, "fields": "title,year,venue,externalIds,citationCount,abstract", "limit": limit})
    req = urllib.request.Request(url, headers={"User-Agent": "research-script"})
    for attempt in range(4):
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.load(r)
        except Exception as e:
            print("  retry", query, e); time.sleep(10)
    return {"data": []}

queries = [
    ("cross_species_pose", "cross-species pose estimation"),
    ("da_animal_pose", "domain adaptation animal pose estimation"),
    ("transfer_ar", "transfer learning action recognition"),
    ("fewshot_ar", "few-shot action recognition"),
    ("ssl_video_small", "self-supervised video pretraining"),
    ("synthetic_animal", "synthetic animal data generation"),
]
out = {}
for k, q in queries:
    d = s2(q)
    out[k] = [{"title": p.get("title"), "year": p.get("year"), "venue": p.get("venue"),
               "arxiv": (p.get("externalIds") or {}).get("ArXiv"),
               "cites": p.get("citationCount"),
               "abstract": (p.get("abstract") or "")[:200]} for p in d.get("data", [])]
    print(k, len(out[k]))
    time.sleep(4)
json.dump(out, open("s2_results.json","w"), ensure_ascii=False, indent=1)
